export function formatMoney(cents: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
}

import { OrderFilters, OrderQueryService, summarizeOrders } from '../../../packages/checkout/src';
import { renderOrderFilters } from './order-filters';
import { renderOrderTable } from './order-table';
import { renderPage } from './page-shell';
import { renderSummaryCards } from './summary-cards';

export class OrderDashboard {
  constructor(private readonly queries: OrderQueryService) {}

  render(tenantId: string, filters: OrderFilters = {}): string {
    const orders = this.queries.list(tenantId, filters);
    return renderPage('Order operations', `<header><p>Commerce operations</p><h1>Orders</h1></header>${renderSummaryCards(summarizeOrders(orders))}${renderOrderFilters(filters)}${renderOrderTable(orders)}`);
  }
}

import { OrderFilters } from '../../../packages/checkout/src';

export function renderOrderFilters(filters: OrderFilters): string {
  const selected = (state: string) => filters.state === state ? ' selected' : '';
  return `<form class="filters" method="get">
    <label>Status <select name="state">
      <option value="">All</option>
      <option value="paid"${selected('paid')}>Paid</option>
      <option value="cancelled"${selected('cancelled')}>Cancelled</option>
    </select></label>
    <label>Minimum total <input name="minimumTotalCents" type="number" min="0" value="${filters.minimumTotalCents ?? ''}"></label>
    <button type="submit">Apply</button>
  </form>`;
}

import { OrderListItem } from '../../../packages/checkout/src';
import { escapeHtml } from './html';
import { formatMoney } from './money-view';
import { renderStatusBadge } from './status-badge';

export function renderOrderTable(orders: OrderListItem[]): string {
  if (orders.length === 0) return '<div class="empty">No orders match these filters.</div>';
  const rows = orders.map((order) => `<tr>
    <td>${escapeHtml(order.id)}</td>
    <td>${escapeHtml(order.customerId)}</td>
    <td>${escapeHtml(order.sku)} × ${order.quantity}</td>
    <td>${formatMoney(order.totalCents)}</td>
    <td>${renderStatusBadge(order.state)}</td>
    <td><time datetime="${new Date(order.placedAt).toISOString()}">${new Date(order.placedAt).toLocaleString('en-US')}</time></td>
  </tr>`).join('');
  return `<table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Status</th><th>Placed</th></tr></thead><tbody>${rows}</tbody></table>`;
}

import { escapeHtml } from './html';

export function renderPage(title: string, content: string): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><link rel="stylesheet" href="/admin.css"></head><body><main>${content}</main></body></html>`;
}

export function renderStatusBadge(state: 'paid' | 'cancelled'): string {
  return `<span class="status status--${state}">${state}</span>`;
}

import { OrderSummary } from '../../../packages/checkout/src';
import { formatMoney } from './money-view';

export function renderSummaryCards(summary: OrderSummary): string {
  return `<section class="summary">
    <article><strong>${summary.orderCount}</strong><span>Orders</span></article>
    <article><strong>${summary.paidCount}</strong><span>Paid</span></article>
    <article><strong>${summary.cancelledCount}</strong><span>Cancelled</span></article>
    <article><strong>${formatMoney(summary.paidRevenueCents)}</strong><span>Paid revenue</span></article>
  </section>`;
}

export function requireIdempotencyKey(headers: Record<string, string | undefined>): string {
  const key = headers['idempotency-key']?.trim();
  if (!key || key.length > 128) throw new Error('invalid idempotency key');
  return key;
}

import { CheckoutService, RetryableCheckoutRequest } from '../../../packages/checkout/src';

export class RetryCheckoutWorker {
  constructor(private readonly checkout: CheckoutService) {}

  run(request: RetryableCheckoutRequest) {
    return this.checkout.place(request);
  }
}

import { CheckoutAttempt } from './checkout-attempt';

export class CheckoutAttemptRepository {
  private readonly values: CheckoutAttempt[] = [];

  start(attempt: CheckoutAttempt): void {
    this.values.push(attempt);
  }

  finish(id: string, state: 'rejected' | 'completed', reason?: string): void {
    const attempt = this.values.find((candidate) => candidate.id === id);
    if (!attempt) throw new Error('checkout attempt not found');
    attempt.state = state;
    attempt.reason = reason;
  }

  all(): CheckoutAttempt[] {
    return this.values.map((attempt) => ({ ...attempt }));
  }
}

export interface CheckoutAttempt {
  id: string;
  tenantId: string;
  idempotencyKey?: string;
  state: 'started' | 'rejected' | 'completed';
  reason?: string;
}

import { PlaceOrderInput } from './checkout-service';

export interface RetryableCheckoutRequest extends PlaceOrderInput {
  idempotencyKey: string;
}

export function requestFingerprint(input: PlaceOrderInput): string {
  return JSON.stringify([
    input.customerId,
    input.sku,
    input.quantity,
    input.unitPriceCents,
    input.promotionBps,
  ]);
}

